css:
.ds-tabs { display:flex; flex-wrap:wrap; align-items:center; gap:4px 20px; min-width:0; max-width:100%; padding:0; margin-bottom:24px; }
.ds-tab { display:inline-flex; align-items:center; justify-content:center; min-height:var(--control-height); padding:10px 0; border:0; border-bottom:1px solid transparent; border-radius:0; background:transparent; font-size:14px; line-height:20px; color:var(--color-ink-soft); white-space:nowrap; cursor:pointer; transition:color 150ms ease-out,border-color 150ms ease-out; }
@media(hover:hover) and (pointer:fine) { .ds-tab:hover { color:var(--color-ink); border-bottom-color:var(--color-border-hover); } }
.ds-tab[aria-pressed=true] { color:var(--color-ink); border-bottom-color:var(--color-ink); font-weight:500; }
.ds-tab:focus-visible { outline:2px solid var(--color-ink); outline-offset:4px; }
@media(prefers-reduced-motion:reduce) { .ds-tab { transition:none; } }
